{
  "unit": 42,
  "font": "sans",
  "points": {
    "B": {"at": [0, 0], "label": "B", "dot": true, "labelDir": "sw"},
    "D": {"at": [0, 6], "label": "D", "dot": true, "labelDir": "n"},
    "C": {"polar": {"center": "B", "r": 5, "deg": 65}, "label": "C", "dot": true, "labelDir": "ne"},
    "A": {"polar": {"center": "D", "r": 4.5, "deg": 210}, "label": "A", "dot": true, "labelDir": "w"}
  },
  "elements": [
    {"type": "polygon", "points": ["B", "D", "C"]},
    {"type": "segment", "from": "A", "to": "D"},
    {"type": "segment", "from": "A", "to": "B"},
    {"type": "segment", "from": "B", "to": "D", "style": "dashed"},
    {"type": "segment", "from": "D", "to": [0, 7.5], "style": "dashed", "arrow": "end"},
    {"type": "text", "at": [0, 7.3], "text": "N", "anchor": "s"},
    {"type": "angle", "at": "B", "a": "D", "b": "C", "label": "30°", "r": 1.2},
    {"type": "angle", "at": "C", "a": "B", "b": "D", "label": "85°", "r": 1.0},
    {"type": "segment", "from": "D", "to": "C", "label": {"text": "9 m", "side": "right"}},
    {"type": "segment", "from": "A", "to": "B", "label": {"text": "14.5 m", "side": "left"}},
    {"type": "segment", "from": "A", "to": "D", "label": {"text": "6 m", "side": "left"}}
  ]
}
